questionvariables.text:
vlist: [
  [1, "for every real number \\(x\\) with \\(x \\geq 0\\), \\(\\sin x \\leq x\\)", "a real number \\(x\\) with \\(x \\geq 0\\)", [x],
      sin(x) > x, x < sin(x), sin(x) >= x, sin(x) <= x,
      "\\(\\sin x \\gt x\\)", "\\(x \\lt \\sin x\\)", "\\(\\sin x \\geq x\\)", "\\(\\sin x \\leq x\\)"],
  [2, "for all real numbers \\(x\\) and \\(y\\), \\(x^2 + xy + y^2 \\geq 0\\)", "real numbers \\(x\\) and \\(y\\)", [x, y],
      x^2+x*y+y^2 < 0, (x+y/2)^2+3*y^2/4 < 0, x^2+x*y+y^2 <= 0, x^2+x*y+y^2 >= 0,
      "\\(x^2 + xy + y^2 \\lt 0\\)", "\\(\\left(x + \\dfrac{y}{2}\\right)^2 + \\dfrac{3y^2}{4} \\lt 0\\)", "\\(x^2 + xy + y^2 \\leq 0\\)", "\\(x^2 + xy + y^2 \\geq 0\\)"],
  [3, "for every real number \\(x\\), \\(x^2 + 1 \\geq 2x\\)", "a real number \\(x\\)", [x],
      x^2+1 < 2*x, (x-1)^2 < 0, x^2+1 <= 2*x, x^2+1 >= 2*x,
      "\\(x^2 + 1 \\lt 2x\\)", "\\((x - 1)^2 \\lt 0\\)", "\\(x^2 + 1 \\leq 2x\\)", "\\(x^2 + 1 \\geq 2x\\)"],
  [4, "for every real number \\(x\\), \\(x^2 - 2x + 3 \\gt 0\\)", "a real number \\(x\\)", [x],
      x^2-2*x+3 <= 0, (x-1)^2+2 <= 0, x^2-2*x+3 < 0, x^2-2*x+3 > 0,
      "\\(x^2 - 2x + 3 \\leq 0\\)", "\\((x - 1)^2 + 2 \\leq 0\\)", "\\(x^2 - 2x + 3 \\lt 0\\)", "\\(x^2 - 2x + 3 \\gt 0\\)"],
  [5, "for all real numbers \\(x\\) and \\(y\\), \\(x^2 + y^2 \\geq 2xy\\)", "real numbers \\(x\\) and \\(y\\)", [x, y],
      x^2+y^2 < 2*x*y, (x-y)^2 < 0, x^2+y^2 <= 2*x*y, x^2+y^2 >= 2*x*y,
      "\\(x^2 + y^2 \\lt 2xy\\)", "\\((x - y)^2 \\lt 0\\)", "\\(x^2 + y^2 \\leq 2xy\\)", "\\(x^2 + y^2 \\geq 2xy\\)"],
  [6, "for every real number \\(x\\) with \\(0 \\leq x \\leq 1\\), \\(x^2 \\leq x\\)", "a real number \\(x\\) with \\(0 \\leq x \\leq 1\\)", [x],
      x^2 > x, x-x^2 < 0, x^2 >= x, x^2 <= x,
      "\\(x^2 \\gt x\\)", "\\(x - x^2 \\lt 0\\)", "\\(x^2 \\geq x\\)", "\\(x^2 \\leq x\\)"]];
vrec: rand(vlist);
vnum: vrec[1];
stmtxt: vrec[2];
domtxt: vrec[3];
relvars: vrec[4];
tarel: vrec[5];
talt: vrec[6];
tnear: vrec[7];
torig: vrec[8];
dtarel: vrec[9];
dtalt: vrec[10];
dtnear: vrec[11];
dtorig: vrec[12];
relnorm(r) := block([o, d], o: op(r), d: lhs(r) - rhs(r), if o = ">" then (o: "<", d: -d) else if o = ">=" then (o: "<=", d: -d), [o, d]);
tstrict: is(first(relnorm(tarel)) = "<");
tbad: lhs(tarel);
ta1: [[qall, false, "every choice"], [qsome, true, "at least one choice"], [qnone, false, "no choice"]];
relmsg: if is(vnum = 1) then "Use only the letter x, and type the sine with brackets, as sin(x)." else "Use only the letters in the statement.";
validate_rel(ex) := if not(member(safe_op(ex), ["<", ">", "<=", ">="])) then "Enter a single inequality, using one of the signs for less than, greater than, at most or at least." else if not(every(lambda([v], member(v, relvars)), listofvars(ex))) then relmsg else "";

feedbackvariables.text:
sN: relnorm(ans2);
tN: relnorm(tarel);
rr: ev(ratsimp(radcan(second(sN)/second(tN))), simp);
samexp: constantp(rr) and is(rr # 0);
pos: samexp and is(rr > 0);
opsame: is(first(sN) = first(tN));
relok: pos and opsame;
relorig: samexp and not(pos) and not(opsame);
relnear: pos and not(opsame);
isall: is(ans1 = qall);
issome: is(ans1 = qsome);
isnone: is(ans1 = qnone);
